import json
with open('/app/resources/treasury_bulletin_1960_10.json', 'r') as f:
    data = json.load(f)

# Let's find all the table data related to 26-week bills
def find_tables(elements):
    results = []
    for el in elements:
        if isinstance(el, dict):
            if el.get('content') and '<table>' in str(el.get('content')):
                results.append(el.get('content'))
            if 'elements' in el:
                results.extend(find_tables(el['elements']))
    return results

tables = find_tables(data['document']['elements'])
